import React, { useState } from "react";
import "./App.css";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.min";
import OffiMekal from "./Component/OffiMekal";
import Home from "./Component/Pages/home/Home";
import ProductList from "./Component/Pages/home/ProductList";
import { Products } from "./Products";
import { Context } from "./Context";
import Footer from "./Component/Footer";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import ProductDetails from "./Component/ProductDetails";
import SearchDetailPage from "./Component/SearchDetailPage";

const App = () => {
  const ProductDetailsHandler = (product) => {
    setProductsDetail(product);
  };
  const [ProductsDetail, setProductsDetail] = useState([]);
  const [serchProductDetails, setSerchProductDetails] = useState([]);
  const searchItemDetailsHandler = (product) => {
    setSerchProductDetails(product);
  };
  console.log(serchProductDetails)
  return (
    <>
      <Context.Provider
        value={{
          products: Products,
          ProductDetailsHandler: ProductDetailsHandler,
          ProductDetails: ProductsDetail,
          serchProductDetails: serchProductDetails,
          setSerchProductDetails: setSerchProductDetails,
          searchItemDetailsHandler: searchItemDetailsHandler,serchProductDetails:serchProductDetails
        }}
      >
        <OffiMekal />
        
          <Routes>
            <Route path="/Mekal" element={<Home />} />
            <Route path="/Mekal/productDetails" Component={ProductDetails} />
            <Route path="/Mekal/serchDetailsPage" Component={SearchDetailPage} />
          </Routes>
        
      </Context.Provider>
      <Footer />
    </>
  );
};

export default App;
