import React, { useContext } from "react";
import './ProductDetail.css'
import { Context } from "../Context";

const SearchDetailPage = () => {
    const { serchProductDetails } = useContext(Context);
    // console.log(serchProductDetails)
  return (
    <>
      <div className="container detail-container">
        <div className="product-imgs">
          <img src={serchProductDetails.img} alt="" className="w-100" />
        </div>
        <div className="product-details">
          <div className="name">
            <h1>{serchProductDetails.name}</h1>
          </div>
          <div className="description">
            <p>{serchProductDetails.description}</p>
          </div>
          <div className="price">
            <h3>&#8377; {serchProductDetails.price}</h3>
          </div>
          <div className="detail-page-btn">
            <button className="btn btn-primary">Add to Cart</button>
            <button className="btn btn-primary">Buy Now</button>
          </div>
        </div>
      </div>
    </>
  );
};

export default SearchDetailPage;
