import React from "react";
import "./Home.css";
import Slider from "react-slick";
import TotalHomeProduct from "./TotalHomeProduct";
import mug from "../../../images/mug.webp";
import ProductList from "./ProductList";
import Hero from "../../Hero";

const Home = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 5, // Default slides to show
    slidesToScroll: 1,
    autoplay: true,
    responsive: [
      {
        breakpoint: 1024, // For screens <= 1024px
        settings: {
          slidesToShow: 4,
          slidesToScroll: 1,
        },
      },
      {
        breakpoint: 768, // For screens <= 768px
        settings: {
          slidesToShow: 2,
          slidesToScroll: 1,
        },
      },
      {
        breakpoint: 480, // For screens <= 480px
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
        },
      },
    ],
  };

  return (
    <>
      <Hero />
      <div className="container-fluid topic-heading">
        <h2 className="heading-name">
          <span className="color-blue">Gift</span> Items
        </h2>
        <div className="dots-line d-flex">
          <div className="line"></div>
          <div className="line-2"></div>
        </div>
      </div>
      <div className="container-fluid">
        <Slider {...settings} className="slider-style">
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 1" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 2" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 3" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 4" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 5" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 6" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 7" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 8" />
          </div>
          <div className="item">
            <img src={mug} className="w-100 h-100" alt="Item 9" />
          </div>
        </Slider>
      </div>
      <TotalHomeProduct />
      <ProductList />
    </>
  );
};

export default Home;
