import React, { useContext, useState } from "react";
import "./SearchBar.css";
import ClickAwayListener from "@mui/material/ClickAwayListener";
import { Context } from "../Context";
import SearchDetailPage from "./SearchDetailPage";
import { products } from "../SearchProduct";
import { Link, NavLink } from "react-router-dom";

const SearchBar = ({ searchItemDetailsHandler }) => {
  // const { searchItemDetailsHandler } = useContext(Context);

  const [filteredProducts, setFilteredProducts] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [open, setOpen] = useState(false);
  // const searchItemDetails = (product) => {
  //   console.log(product.id);
  // };
  const [searchItems, setSearchItems] = useState([]);
  const searchItemClick = (product) => {
    setSearchItems(product);
    setOpen(false);
    setSearchTerm("");
  };
  const handleClickAway = () => {
    setOpen(false);
    setSearchTerm("");
  };

  const searchHandler = (e) => {
    const value = e.target.value;

    setSearchTerm(value);
    setOpen(value.length > 0);

    // console.log(searchTerm);
    if (value) {
      const filtered = products.filter((products) =>
        products.name.toLowerCase().includes(value.toLowerCase())
      );
      setFilteredProducts(filtered);
    } else {
      setFilteredProducts([]);
    }
  };
  return (
    <>
      <ClickAwayListener onClickAway={handleClickAway}>
        <div>
          <input
            className="search-input"
            type="text"
            placeholder="Search here..."
            value={searchTerm}
            onChange={searchHandler}
          />
          {open && (
            <div className="search-results">
              {filteredProducts.map((product) => (
                <Link to={"Mekal/serchDetailsPage"}>
                  <div
                    className="product-list-card"
                    key={product.id}
                    onClick={() => {
                      searchItemDetailsHandler(product);
                      searchItemClick(product);
                    }}
                  >
                    <div className="product-img-div">
                      <img src={product.img} alt="Product" className="w-100" />
                    </div>

                    <div className="product-name">
                      <h3>{product.name}</h3>
                    </div>
                    <div className="product-price">
                      <h6>{product.price}</h6>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>
      </ClickAwayListener>
    </>
  );
};

export default SearchBar;
