import React, { useContext } from "react";
import "./ProductList.css";
import { Context } from "../../../Context";
import mug from "../../../images/mug.webp";
import { Link } from "react-router-dom";

const ProductList = () => {
  const { products, ProductDetailsHandler } = useContext(Context);
  // console.log(products)
  return (
    <div className="ProductList-container">
      <div className="container-fluid topic-heading">
        <h2 className="heading-name">
          <span className="color-blue">All</span> Products
        </h2>
        <div className="dots-line d-flex">
          {/* <div className="dots">
            <div className="dot-list"></div>
            <div className="dot-list"></div>
            <div className="dot-list"></div>
          </div> */}

          <div className="line"></div>
          <div className="line-2"></div>
        </div>
      </div>
      <div className="container">
        <div className="Product-container">
          {products.map((product) => {
            return (
              <div
                  key={product.id}
                  className="card liquid"
                  onClick={() => ProductDetailsHandler(product)}
                >
                <Link to={"/Mekal/productDetails"} className="product-link">
                  <div className="product-img">
                    <img src={mug} alt="" className="w-100" />
                  </div>
                  <div className="card-body">
                    <h3>{product.name}</h3>
                    {/* <p>{product.description}</p> */}
                    <h4>{product.price}</h4>
                    <button className="btn btn-primary">Add to Cart</button>
                  </div>
              </Link>
                </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default ProductList;
